    $typeTokenLookup[$typeTokenId] = true;
}

$isConstantDeclarationName = false;
if (null === $nextNeighbourId && '=' === $nextNeighbourContent) {
    $constSearchCursor = $previousIndex;
    while (true) {
        if (!$tokens->offsetExists($constSearchCursor)) {
            break;
        }

        $constCandidate = $tokens[$constSearchCursor];
        $constCandidateId = $constCandidate->getId();
        if (null === $constCandidateId) {
            if (\in_array($constCandidate->getContent(), ['?', '|', '&', '(', ')'], true)) {
                --$constSearchCursor;
                continue;
            }
            break;
        }

        if (T_CONST === $constCandidateId) {
            $isConstantDeclarationName = true;
            break;
        }

        if (isset($typeTokenLookup[$constCandidateId])) {
            --$constSearchCursor;
            continue;
        }

        break;
    }
}

$shouldFixConstant = false;
if ($previousNeighbourAccepted) {
    if ($nextNeighbourAccepted) {
        if (!$isEnumCaseName && !$isConstantDeclarationName) {
            $shouldFixConstant = true;
        }
    }
}

